js:function(context, args) {
  args = args || {};
  var missing = [];
  if (!args.url) missing.push("url");
  if (!args.session) missing.push("session");
  if (!args.term) missing.push("term");
  if (!args.input_selector) missing.push("input_selector");
  if (!args.submit_selector) missing.push("submit_selector");
  if (missing.length) return {defer: "missing current arguments", parameters: "url, session, term, input_selector, submit_selector"};
  var session = args.session;
  var term = String(args.term);
  var inSel = String(args.input_selector);
  var btnSel = String(args.submit_selector);
  var prefix = (args.receipt_prefix == null) ? "Receipt: " : String(args.receipt_prefix);

  function snap(data) {
    if (!data || !data.elements) return null;
    return data.elements;
  }
  function findIdx(elements) {
    if (!elements) return -1;
    for (var i = 0; i < elements.length; i++) {
      var t = elements[i].text;
      if (t && t.indexOf(prefix) === 0) return i;
    }
    return -1;
  }
  function reportFor(elements, hostCall) {
    var idx = findIdx(elements);
    if (idx < 0) return null;
    return {report: {evidence: hostCall, path: ["data", "elements", idx, "text"]}};
  }

  var hostCall = null;
  var elements = null;
  var opened = false;
  var filled = false;
  var clicked = false;
  var anySnapshot = false;
  var postClickSnapshot = false;

  var hist = context.history || [];
  for (var h = 0; h < hist.length; h++) {
    var rec = hist[h];
    if (rec.name !== "bash") continue;
    var av = (rec.decoded_argv || []).slice();
    if (av[0] !== "playwright") continue;
    var sub = av[1];
    if (sub === "open" && av[2] === args.url && av.indexOf("--session") >= 0) { opened = true; }
    if (sub === "fill" && av[2] === session && av[3] === inSel && av[4] === term) { filled = true; }
    if (sub === "click" && av[2] === session && av[3] === btnSel) { clicked = true; }
    if (sub === "snapshot" && av[2] === session && rec.data) {
      elements = snap(rec.data);
      if (rec.call_id) hostCall = rec.call_id;
      anySnapshot = true;
      if (clicked) postClickSnapshot = true;
    }
  }

  if (clicked && postClickSnapshot && elements) {
    var done = reportFor(elements, hostCall);
    if (done) return done;
  }

  if (!opened) {
    var o = execute({name: "bash", arguments: {command: command("playwright", ["open", args.url, "--session", session])}, read: false, step: "open", occurrence: 0});
    if (o && o.is_error) return {defer: "open failed: " + (o.text || "unknown")};
  }

  if (!anySnapshot) {
    var s1 = execute({name: "bash", arguments: {command: command("playwright", ["snapshot", session, "--json"])}, read: true});
    if (s1 && s1.call_id) hostCall = s1.call_id;
    elements = snap(s1 && s1.data);
  }

  if (!filled) {
    var f = execute({name: "bash", arguments: {command: command("playwright", ["fill", session, inSel, term])}, read: false, step: "fill", occurrence: 0});
    if (f && f.is_error) return {defer: "fill failed: " + (f.text || "unknown")};
  }

  if (!clicked) {
    var c = execute({name: "bash", arguments: {command: command("playwright", ["click", session, btnSel])}, read: false, step: "click", occurrence: 0});
    if (c && c.is_error) return {defer: "click failed: " + (c.text || "unknown")};
  }

  if (!postClickSnapshot) {
    var s2 = execute({name: "bash", arguments: {command: command("playwright", ["snapshot", session, "--json"])}, read: true});
    if (s2 && s2.call_id) hostCall = s2.call_id;
    var e2 = snap(s2 && s2.data);
    var p2 = reportFor(e2, hostCall);
    if (p2) return p2;
  }
  return {defer: "receipt not yet visible after submit"};
}
